// Icons extracted from the original app's icon sheet are filled silhouettes
// (the "line" look is baked into the compound path itself), unlike the
// hand-drawn UI-chrome icons above which are open strokes.
const FILL_ICONS = new Set(['art', 'badge', 'bag', 'beer', 'bike', 'binoculars', 'bird', 'book', 'briefcase', 'bus', 'call', 'camera', 'car', 'card', 'cart', 'cherries', 'cigarette', 'clock', 'clothes', 'coffee', 'cow', 'dental', 'diamond', 'diaper', 'dinner', 'dollar', 'drink', 'education', 'factory', 'fishing', 'food', 'fuel', 'gamepad', 'gift', 'goggles', 'headphones', 'health', 'heart', 'heels', 'home', 'key', 'leaf', 'lips', 'man', 'medal', 'moneybag', 'music', 'pacifier', 'palm', 'paw', 'people', 'percent', 'piechart', 'repair', 'ship', 'ski', 'sport', 'star', 'stroller', 'tie', 'tire', 'tools', 'travel', 'wallet', 'wifi', 'woman']);

function icon(name, cls) {
  const inner = ICONS[name] || ICONS.other;
  const classAttr = `icon${cls ? " " + cls : ""}`;
  if (FILL_ICONS.has(name)) {
    return `<svg class="${classAttr}" viewBox="0 0 24 24" fill="currentColor" fill-rule="nonzero" stroke="none">${inner}</svg>`;
  }
  return `<svg class="${classAttr}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
}

// Category icon field may hold either an SVG icon key or a literal emoji
// typed via the iOS emoji keyboard. This renders whichever it is.
function renderCatIcon(value) {
  if (ICONS[value]) return icon(value);
  return `<span class="emoji-ic">${value || "?"}</span>`;
}
